#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    int *buffer;
    int capacity;
    int size;
    int head;
    int tail;
} CircularBuffer;

CircularBuffer* create_buffer(int initial_capacity) {
    CircularBuffer *cb = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    if (!cb) return NULL;
    cb->buffer = (int*)calloc(initial_capacity, sizeof(int));
    if (!cb->buffer) {
        free(cb);
        return NULL;
    }
    cb->capacity = initial_capacity;
    cb->size = 0;
    cb->head = 0;
    cb->tail = 0;
    return cb;
}

void print_buffer(CircularBuffer *cb) {
    if (!cb || cb->size == 0) {
        printf("\n");
        return;
    }
    for (int i = 0; i < cb->size; i++) {
        int idx = (cb->head + i) % cb->capacity;
        printf("%d", cb->buffer[idx]);
        if (i < cb->size - 1) {
            printf(" ");
        }
    }
    printf("\n");
}

void destroy_buffer(CircularBuffer *cb) {
    if (cb) {
        free(cb->buffer);
        free(cb);
    }
}

void add_element(CircularBuffer **cb_ptr, int value) {
    CircularBuffer *cb = *cb_ptr;
    if (cb->size == cb->capacity) {
        int new_capacity = cb->capacity * 2;
        int *new_buffer = (int*)realloc(cb->buffer, new_capacity * sizeof(int));
        if (!new_buffer) return;
        cb->buffer = new_buffer;
        if (cb->tail < cb->head) {
            memmove(cb->buffer + new_capacity, cb->buffer, cb->size * sizeof(int));
            cb->tail += cb->capacity;
        }
        cb->capacity = new_capacity;
    }
    cb->buffer[cb->tail] = value;
    cb->tail = (cb->tail + 1) % cb->capacity;
    cb->size++;
}

void remove_element(CircularBuffer **cb_ptr) {
    CircularBuffer *cb = *cb_ptr;
    if (cb->size > 0) {
        cb->head = (cb->head + 1) % cb->capacity;
        cb->size--;
    }
}

void resize_buffer(CircularBuffer **cb_ptr, int new_size) {
    CircularBuffer *cb = *cb_ptr;
    if (new_size <= 0) return;
    if (new_size >= cb->size) {
        int *new_buffer = (int*)realloc(cb->buffer, new_size * sizeof(int));
        if (!new_buffer) return;
        cb->buffer = new_buffer;
        if (cb->tail < cb->head) {
            memmove(cb->buffer + new_size, cb->buffer, cb->size * sizeof(int));
            cb->tail += cb->capacity;
        }
        cb->capacity = new_size;
    } else {
        int *new_buffer = (int*)malloc(new_size * sizeof(int));
        if (!new_buffer) return;
        for (int i = 0; i < new_size && i < cb->size; i++) {
            int src_idx = (cb->head + cb->size - 1 - i) % cb->capacity;
            new_buffer[i] = cb->buffer[src_idx];
        }
        free(cb->buffer);
        cb->buffer = new_buffer;
        cb->capacity = new_size;
        cb->size = new_size;
        cb->head = 0;
        cb->tail = new_size;
    }
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    CircularBuffer *cb = create_buffer(10);

    char op[10];
    for (int i = 0; i < n; i++) {
        if (scanf("%s", op) != 1) break;

        if (strcmp(op, "ADD") == 0) {
            int val;
            if (scanf("%d", &val) == 1) {
                add_element(&cb, val);
            }
        } else if (strcmp(op, "REMOVE") == 0) {
            remove_element(&cb);
        } else if (strcmp(op, "RESIZE") == 0) {
            int new_size;
            if (scanf("%d", &new_size) == 1) {
                resize_buffer(&cb, new_size);
            }
        }
        print_buffer(cb);
    }

    destroy_buffer(cb);
    return 0;
}
